import java.util.*;

public class Main {
    static String[] createQuestion(String q, String a, String b, String c, String d, String correct) {
        return new String[]{q, a, b, c, d, correct};
    }

    static ArrayList<String[]> getJavaQuestions() {
        ArrayList<String[]> list = new ArrayList<>();
        list.add(createQuestion("Which keyword is used to create a subclass in Java?",
                "A) implements", "B) extends", "C) inherits", "D) override", "B"));
        list.add(createQuestion("What is the output of: 10 + 20 + \"Java\"?",
                "A) 30Java", "B) Java1020", "C) Java30", "D) 1020Java", "A"));
        return list;
    }

    public static void main(String[] args) {
        ArrayList<String[]> questions = getJavaQuestions();
        Collections.shuffle(questions);
        System.out.println("Loaded and shuffled " + questions.size() + " questions.");
    }
}

public class Main {
    static void countdownTimer(int seconds) {
        System.out.println("You have " + seconds + " seconds to think...");
        for (int i = seconds; i > 0; i--) {
            System.out.print("\rTime left: " + i + " seconds ");
            System.out.flush();
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        System.out.println("\rTime is up!               ");
    }

    public static void main(String[] args) {
        countdownTimer(3); // Demo with 3 seconds
    }
}

public class Main {
    static void displayQuestion(String[] qData, int qNumber) {
        System.out.println("====================");
        System.out.println("Question " + qNumber + ": " + qData[0]);
        System.out.println(qData[1]);
        System.out.println(qData[2]);
        System.out.println(qData[3]);
        System.out.println(qData[4]);
    }

    public static void main(String[] args) {
        String[] sample = {"Which keyword creates a subclass?", "A) implements", "B) extends", "C) inherits", "D) override", "B"};
        displayQuestion(sample, 1);
    }
}

import java.util.*;

public class Main {
    static String getUserAnswer(Scanner scanner) {
        System.out.print("Enter your answer (A, B, C, or D): ");
        if (!scanner.hasNextLine()) return null;
        String input = scanner.nextLine().trim().toUpperCase();
        if (input.equals("A") || input.equals("B") || input.equals("C") || input.equals("D")) {
            return input;
        }
        return null; // Invalid input
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner("  b  \n");
        String ans = getUserAnswer(sc);
        System.out.println("Captured normalized answer: " + ans);
    }
}

public class Main {
    static int checkAnswer(String userAns, String correctAns) {
        if (userAns != null && userAns.equalsIgnoreCase(correctAns)) {
            System.out.println("Answer is correct!");
            return 1;
        } else {
            System.out.println("Your answer is wrong! The correct answer is " + correctAns + ".");
            return 0;
        }
    }

    static int updateScore(int currentScore, int result) {
        return currentScore + result;
    }

    public static void main(String[] args) {
        int score = 0;
        int res = checkAnswer("B", "B");
        score = updateScore(score, res);
        System.out.println("Current score: " + score);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        ArrayList<String[]> questions = new ArrayList<>();
        questions.add(new String[]{"Which keyword creates a subclass?", "A) implements", "B) extends", "C) inherits", "D) override", "B"});
        Collections.shuffle(questions);

        int score = 0;
        int qNum = 1;
        for (String[] q : questions) {
            System.out.println("Question " + qNum + ": " + q[0]);
            System.out.println(q[1] + "\n" + q[2] + "\n" + q[3] + "\n" + q[4]);
            String simulatedAnswer = "B";
            if (simulatedAnswer.equals(q[5])) {
                System.out.println("Correct!");
                score++;
            }
            qNum++;
        }
        System.out.println("Final score: " + score + "/" + questions.size());
    }
}

