import java.util.*;

public class Main {
    // Single pass to find max value in O(n) time
    static int findMax(int[] arr) {
        if (arr == null || arr.length == 0) throw new IllegalArgumentException("Array empty");
        int max = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i]; // Update running answer on the fly
            }
        }
        return max;
    }

    public static void main(String[] args) {
        int[] data = {14, 28, 9, 45, 32};
        System.out.println("Maximum: " + findMax(data));
    }
}

import java.util.*;

public class Main {
    // Filter even numbers into a new result collection without mutating input
    static ArrayList<Integer> filterEvens(List<Integer> numbers) {
        ArrayList<Integer> result = new ArrayList<>();
        for (int num : numbers) {
            if (num % 2 == 0) {
                result.add(num);
            }
        }
        return result;
    }

    public static void main(String[] args) {
        List<Integer> list = Arrays.asList(1, 2, 3, 4, 5, 6);
        System.out.println("Filtered evens: " + filterEvens(list));
    }
}

import java.util.*;

public class Main {
    // Safe in-place removal using Iterator to prevent ConcurrentModificationException
    static void removeNegatives(List<Integer> list) {
        Iterator<Integer> it = list.iterator();
        while (it.hasNext()) {
            if (it.next() < 0) {
                it.remove(); // Safe element deletion during traversal
            }
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<>(Arrays.asList(10, -5, 20, -1, 30));
        removeNegatives(nums);
        System.out.println("Non-negative numbers: " + nums);
    }
}

import java.util.*;

public class Main {
    // Problem: Check if array contains any duplicates
    // Time: O(n), Space: O(n) using HashSet
    static boolean hasDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (!seen.add(num)) {
                return true; // Duplicate found
            }
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println("Has dup [1,2,3,1]: " + hasDuplicate(new int[]{1, 2, 3, 1}));
        System.out.println("Has dup [1,2,3,4]: " + hasDuplicate(new int[]{1, 2, 3, 4}));
    }
}

